<?php declare(strict_types=1); require_once __DIR__.'/../includes/auth.php'; require_auth(); require_once __DIR__.'/../includes/csrf.php'; require_once __DIR__.'/../config/database.php'; $page_title='Create document';$page_heading='Create document';$active_page='create';$users=$conn->query("SELECT id,fname,mname,lname,designation,department FROM dr_users WHERE status <> 'Inactive' ORDER BY department,lname,fname")->fetch_all(MYSQLI_ASSOC);require __DIR__.'/../includes/app-shell.php'; ?>
<section class="panel"><form method="post" action="<?= url('actions/create-document.php') ?>" class="form-grid"><?= csrf_input() ?><div class="field"><label for="title">Document title</label><input id="title" name="title" maxlength="50" required></div><div class="field"><label for="receiver_id">Forward to</label><select id="receiver_id" name="receiver_id" required><option value="">Select a recipient</option><?php foreach($users as $recipient): if((int)$recipient['id']===(int)$_SESSION['user_id'])continue; ?><option value="<?= $recipient['id'] ?>"><?= e($recipient['department'].' — '.user_name($recipient).' ('.$recipient['designation'].')') ?></option><?php endforeach; ?></select></div><div class="field field-full"><label for="description">Document description</label><textarea id="description" name="description" maxlength="500" required></textarea></div><div class="field field-full"><label for="remarks">Remarks <small>(optional)</small></label><textarea id="remarks" name="remarks" maxlength="500"></textarea></div><div class="form-actions field-full"><a class="btn btn-secondary" href="<?= url('dashboard.php') ?>">Cancel</a><button class="btn" type="submit">Create and route document</button></div></form></section><?php require __DIR__.'/../includes/footer.php'; ?>
